import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { useLocation } from 'react-router-dom';
import { usePageSEO } from '../hooks/usePageSEO';
import { buildOrganizationSchema } from '../utils/schemas';
import { isNonProductionHost } from '../utils/seoHost';
import { useSEOHeadConfig } from './SEOHeadContext';

export interface SEOHeadProps {
  title: string;
  description: string;
  keywords?: string[];
  ogImage?: string;
  ogType?: 'website' | 'article';
  noIndex?: boolean;
  structuredData?: Record<string, unknown> | Record<string, unknown>[];
}

/**
 * Per-route SEO component.
 *
 * Reads app-level config from `SEOHeadProvider`, derives canonical URL and
 * language from the current route, builds the WebApplication schema, and
 * delegates all DOM manipulation to `usePageSEO`.
 *
 * Pages provide localized title, description, keywords, and structured data.
 * This component handles everything else automatically.
 */
export function SEOHead({
  title,
  description,
  keywords,
  ogImage,
  ogType = 'website',
  noIndex = false,
  structuredData,
}: SEOHeadProps) {
  const config = useSEOHeadConfig();
  const { i18n } = useTranslation();
  const location = useLocation();
  const lang = i18n.language || 'en';
  const {
    baseUrl,
    appName,
    defaultOgImage,
    twitterHandle,
    supportedLanguages,
    languageHreflangMap,
    defaultLanguage,
    applicationCategory,
    applicationSubCategory,
    howtoNamespace = 'howto',
    organizationName,
    supportEmail,
    foundingDate,
  } = config;

  // Canonical URL: use language from the URL path (not i18n preference)
  const urlLangMatch = location.pathname.match(/^\/([a-z]{2}(-[a-z]+)?)(\/|$)/);
  const urlLang = urlLangMatch ? urlLangMatch[1] : lang;
  const rawPathWithoutLang = location.pathname.replace(
    /^\/[a-z]{2}(-[a-z]+)?(\/|$)/,
    '/'
  );
  // Normalize to NO trailing slash (source of truth) to match the sitemap and
  // prerender convention (e.g. /en, /en/techniques/x-wing). The language root
  // collapses to '' so the canonical is /en, not /en/. Canonical and every
  // hreflang alternate are derived from this same value, so they stay
  // byte-for-byte identical — a prerequisite for a valid hreflang cluster.
  const pathWithoutLang =
    rawPathWithoutLang === '/' ? '' : rawPathWithoutLang.replace(/\/+$/, '');
  const canonical = `${baseUrl}/${urlLang}${pathWithoutLang}`;

  const shouldNoIndex = noIndex || isNonProductionHost();

  // WebApplication schema — always included, localized
  const { t: tHowTo } = useTranslation(howtoNamespace);
  const webAppSchema = useMemo(
    () => ({
      '@context': 'https://schema.org',
      '@type': 'WebApplication',
      name: appName,
      url: baseUrl,
      applicationCategory,
      ...(applicationSubCategory ? { applicationSubCategory } : {}),
      description: tHowTo('webApp.description'),
      operatingSystem: 'Web',
      dateModified: new Date().toISOString().split('T')[0],
      offers: { '@type': 'Offer', price: '0', priceCurrency: 'USD' },
      featureList: (() => {
        const raw = tHowTo('webApp.features', { returnObjects: true });
        return Array.isArray(raw) ? raw : [];
      })(),
    }),
    [appName, baseUrl, applicationCategory, applicationSubCategory, tHowTo]
  );

  // Organization schema — always included, localized description
  const orgSchema = useMemo(
    () =>
      buildOrganizationSchema({
        name: organizationName || appName,
        url: baseUrl,
        logoUrl: defaultOgImage,
        description: tHowTo('webApp.description'),
        supportEmail,
        foundingDate,
        supportedLanguages,
      }),
    [
      organizationName,
      appName,
      baseUrl,
      defaultOgImage,
      tHowTo,
      supportEmail,
      foundingDate,
      supportedLanguages,
    ]
  );

  // Combine WebApplication + Organization + page-specific schemas
  const pageSchemas = structuredData
    ? Array.isArray(structuredData)
      ? structuredData
      : [structuredData]
    : [];
  const schemas = useMemo(
    () => [webAppSchema, orgSchema, ...pageSchemas],
    [webAppSchema, orgSchema, JSON.stringify(pageSchemas)]
  );

  // Single hook handles all DOM manipulation
  usePageSEO(
    {
      title,
      description,
      keywords: Array.isArray(keywords) ? keywords : undefined,
      canonical,
      lang: urlLang,
      pathWithoutLang,
      ogImage,
      ogType,
      noIndex: shouldNoIndex,
      structuredData: schemas,
    },
    {
      appName,
      baseUrl,
      defaultOgImage,
      twitterHandle,
      supportedLanguages,
      languageHreflangMap,
      defaultLanguage,
    }
  );

  return null;
}
